contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint256 beforeC = address(c).balance;
        uint256 beforeMe = address(this).balance;
        uint256 beforeBal = c.balances(address(this));

        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }

        uint256 afterC = address(c).balance;
        uint256 afterMe = address(this).balance;
        uint256 afterBal = c.balances(address(this));

        if (beforeBal > 0) {
            if (reverted) {
                assert(afterBal == beforeBal && afterC == beforeC);
            } else {
                assert(afterBal == 0 && afterC + beforeBal == beforeC && afterMe == beforeMe + beforeBal);
            }
        } else {
            assert(reverted || (afterBal == 0));
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address sender, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // seed the sender's balance via a value-bearing fallback call
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);
        // read the before-values through the public surface
        uint256 beforeBal = c.balances(address(this));
        uint256 beforeC = address(c).balance;
        uint256 beforeMe = address(this).balance;

        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }

        uint256 afterBal = c.balances(address(this));
        uint256 afterC = address(c).balance;
        uint256 afterMe = address(this).balance;

        assert(
            (beforeBal == 0 && reverted && afterBal == 0 && afterC == beforeC && afterMe == beforeMe)
            ||
            (beforeBal > 0 && reverted && afterBal == beforeBal && afterC == beforeC && afterMe == beforeMe)
            ||
            (beforeBal > 0 && !reverted && afterBal == 0 && afterC + beforeBal == beforeC && afterMe == beforeMe + beforeBal)
        );
    }
}

