contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 depositAmount) public payable {
        require(depositAmount > 0, "deposit amount must be positive");

        uint256 cBefore = address(c).balance;

        // Optionally fund the caller's balance by sending Ether to c via the fallback from this test contract.
        // Since msg.sender for the c fallback will be this test contract, we can deposit using c.f{value: depositAmount}()
        if (depositAmount > 0) {
            c.call{value: depositAmount}("");
        }

        // Record balances before withdraw for caller and a few other addresses.
        uint256 callerBalanceBefore = c.balances(caller);
        uint256 testContractBalanceBefore = c.balances(address(this));
        address someAddr = address(0xdead);
        uint256 otherBalanceBefore = c.balances(someAddr);

        // Withdraw from caller address.
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Post-conditions:
        // If withdraw succeeded, the caller's balance must be zero and c's balance must be unchanged relative to before withdraw,
        // and all other balances remain as before.
        // If withdraw reverted, nothing changes.
        if (!reverted) {
            // After successful withdraw, caller's balance must be zero.
            assert(c.balances(caller) == 0);
            // The contract's Ether balance must be the same as before withdraw (since the test contract had deposited).
            // For a fresh contract with no prior deposits, cBefore is zero; after successful withdraw, balance should be zero.
            assert(address(c).balance == cBefore + depositAmount - callerBalanceBefore);
            // The test contract's balance should be unchanged (it did not call withdraw successfully from caller unless caller == address(this)).
            if (caller != address(this)) {
                assert(c.balances(address(this)) == testContractBalanceBefore);
            }
            // Other addresses' balances remain unchanged.
            assert(c.balances(someAddr) == otherBalanceBefore);
        } else {
            // If reverted, balances should be unchanged.
            assert(c.balances(caller) == callerBalanceBefore);
            assert(c.balances(address(this)) == testContractBalanceBefore);
            assert(c.balances(someAddr) == otherBalanceBefore);
            assert(address(c).balance == cBefore + depositAmount);
        }
    }

    receive() external payable {}
}

