    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        uint256 beforeBal = address(c).balance;
        c.fallback{value: depositAmount}();
        uint256 preCallerBal = c.balances(address(this));
        require(preCallerBal == depositAmount);
        (bool withdrawOk, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        uint256 postCallerBal = c.balances(address(this));
        uint256 postContractBal = address(c).balance;
        assert(withdrawOk && postCallerBal == 0 && postContractBal + depositAmount == beforeBal);
    }

    receive() external payable {}
}

