        // is nonzero. When it succeeds, the caller's pre-call balance must have been
        // zero, so no Ether leaves the contract on that path.
        assert(
            reverted == (balanceBefore != 0) &&
            (reverted || address(c).balance == contractBalanceBefore) &&
            (reverted || balanceAfter == 0)
        );
    }

    receive() external payable {}
}

